from __future__ import annotations

import numpy as np
import pandas as pd


def trailing_return(series: pd.Series, trading_days: int) -> float:
    clean = series.dropna()
    if len(clean) <= trading_days:
        return float("nan")
    return float(clean.iloc[-1] / clean.iloc[-trading_days - 1] - 1)


def max_drawdown(series: pd.Series) -> float:
    cumulative_max = series.cummax()
    drawdowns = series / cumulative_max - 1
    return float(drawdowns.min())


def _normalize(values: pd.Series) -> pd.Series:
    values = values.astype(float)
    min_value = values.min()
    max_value = values.max()
    if pd.isna(min_value) or pd.isna(max_value) or np.isclose(min_value, max_value):
        return pd.Series(0.5, index=values.index, dtype=float)
    return (values - min_value) / (max_value - min_value)


TREND_SCORE_WEIGHTS: dict[str, float] = {
    "screen_hits": 0.20,
    "day_change_pct": 0.15,
    "return_5d": 0.15,
    "return_21d": 0.20,
    "return_63d": 0.15,
    "dollar_volume": 0.15,
}


def compute_security_metrics(candidates: pd.DataFrame, price_history: pd.DataFrame) -> pd.DataFrame:
    available = [ticker for ticker in candidates["symbol"].tolist() if ticker in price_history.columns]
    if not available:
        raise ValueError("None of the candidate tickers were present in the downloaded price history.")

    aligned_candidates = candidates[candidates["symbol"].isin(available)].copy()
    metrics_rows: list[dict] = []

    for ticker in available:
        prices = price_history[ticker].dropna()
        daily_returns = prices.pct_change().dropna()
        metrics_rows.append(
            {
                "symbol": ticker,
                "latest_close": float(prices.iloc[-1]),
                "return_5d": trailing_return(prices, 5),
                "return_21d": trailing_return(prices, 21),
                "return_63d": trailing_return(prices, 63),
                "ann_volatility": float(daily_returns.std() * np.sqrt(252)) if not daily_returns.empty else float("nan"),
                "max_drawdown": max_drawdown(prices) if not prices.empty else float("nan"),
            }
        )

    metrics = pd.DataFrame(metrics_rows)
    combined = aligned_candidates.merge(metrics, on="symbol", how="inner")
    combined["dollar_volume"] = combined["latest_close"] * combined["avg_volume_3m"].fillna(0)
    return combined


def rank_trending_stocks(metrics: pd.DataFrame, top_n: int) -> pd.DataFrame:
    ranked = metrics.copy()
    for column in TREND_SCORE_WEIGHTS:
        ranked[f"{column}_norm"] = _normalize(ranked[column].fillna(0))

    ranked["trend_score"] = sum(
        ranked[f"{column}_norm"] * weight for column, weight in TREND_SCORE_WEIGHTS.items()
    )
    ranked = ranked.sort_values(
        ["trend_score", "screen_hits", "dollar_volume"],
        ascending=[False, False, False],
    ).reset_index(drop=True)
    ranked.insert(0, "rank", range(1, len(ranked) + 1))
    return ranked.head(top_n).copy()


def equal_weight_portfolio_returns(price_history: pd.DataFrame) -> pd.Series:
    daily_returns = price_history.pct_change().dropna(how="all")
    weights = np.repeat(1 / daily_returns.shape[1], daily_returns.shape[1])
    return pd.Series(daily_returns.to_numpy().dot(weights), index=daily_returns.index, name="portfolio_return")


def portfolio_summary(price_history: pd.DataFrame, benchmark: pd.Series, risk_free_rate: float) -> pd.DataFrame:
    portfolio_returns = equal_weight_portfolio_returns(price_history)
    cumulative = (1 + portfolio_returns).cumprod()
    annual_return = float(portfolio_returns.mean() * 252)
    annual_volatility = float(portfolio_returns.std() * np.sqrt(252))
    sharpe = float((annual_return - risk_free_rate) / annual_volatility) if annual_volatility else float("nan")
    total_return = float(cumulative.iloc[-1] - 1)

    benchmark_returns = benchmark.pct_change().dropna()
    benchmark_total_return = float((1 + benchmark_returns).cumprod().iloc[-1] - 1)

    return pd.DataFrame(
        [
            {"metric": "Portfolio total return (lookback)", "value": total_return},
            {"metric": "Portfolio annualized return", "value": annual_return},
            {"metric": "Portfolio annualized volatility", "value": annual_volatility},
            {"metric": "Portfolio Sharpe ratio", "value": sharpe},
            {"metric": "Portfolio max drawdown", "value": max_drawdown(cumulative)},
            {"metric": f"{benchmark.name} total return (lookback)", "value": benchmark_total_return},
        ]
    )


def correlation_matrix(price_history: pd.DataFrame) -> pd.DataFrame:
    return price_history.pct_change().dropna(how="all").corr()

from __future__ import annotations
from dataclasses import dataclass from pathlib import Path
@dataclass(frozen=True) class AnalysisConfig: project_root: Path = Path(__file__).resolve().parents[2] top_n: int = 5 screener_queries: tuple[str, ...] = ( "most_actives", "day_gainers", "growth_technology_stocks", ) screener_count: int = 25 price_history_period: str = "6mo" benchmark_ticker: str = "SPY" min_price: float = 5.0 min_market_cap: int = 10_000_000_000 allowed_exchanges: tuple[str, ...] = ("NMS", "NYQ", "ASE", "NGM") fallback_universe: tuple[str, ...] = ( "AAPL", "AMD", "AMZN", "AVGO", "CRM", "GOOGL", "HOOD", "INTC", "JPM", "META", "MSFT", "NFLX", "NVDA", "ORCL", "PLTR", "SHOP", "TSLA", ) risk_free_rate: float = 0.04 monte_carlo_simulations: int = 250 monte_carlo_days: int = 252 random_seed: int = 42
@property def data_dir(self) -> Path: return self.project_root / "data" / "processed"
@property def reports_dir(self) -> Path: return self.project_root / "reports"
@property def figures_dir(self) -> Path: return self.reports_dir / "figures"

from __future__ import annotations

from typing import Iterable

import pandas as pd
import yfinance as yf

from .config import AnalysisConfig


def _as_dataframe(records: list[dict]) -> pd.DataFrame:
    if not records:
        return pd.DataFrame(
            columns=[
                "screen",
                "symbol",
                "name",
                "quote_type",
                "exchange",
                "price",
                "day_change_pct",
                "market_cap",
                "avg_volume_3m",
            ]
        )
    return pd.DataFrame.from_records(records)


def fetch_screener_candidates(config: AnalysisConfig) -> tuple[pd.DataFrame, str]:
    records: list[dict] = []
    failures: dict[str, str] = {}

    for screen_name in config.screener_queries:
        try:
            response = yf.screen(screen_name, count=config.screener_count)
            quotes = response.get("quotes", [])
            for quote in quotes:
                records.append(
                    {
                        "screen": screen_name,
                        "symbol": quote.get("symbol"),
                        "name": quote.get("longName") or quote.get("shortName") or quote.get("symbol"),
                        "quote_type": quote.get("quoteType"),
                        "exchange": quote.get("exchange"),
                        "price": quote.get("regularMarketPrice"),
                        "day_change_pct": quote.get("regularMarketChangePercent"),
                        "market_cap": quote.get("marketCap"),
                        "avg_volume_3m": quote.get("averageDailyVolume3Month"),
                    }
                )
        except Exception as exc:  # pragma: no cover - network-dependent path
            failures[screen_name] = str(exc)

    frame = _as_dataframe(records)
    if not frame.empty:
        frame = frame.dropna(subset=["symbol"]).copy()
        frame = frame[
            (frame["quote_type"] == "EQUITY")
            & (frame["exchange"].isin(config.allowed_exchanges))
        ].copy()
        frame = frame[
            (frame["price"].fillna(0) >= config.min_price)
            & (frame["market_cap"].fillna(0) >= config.min_market_cap)
        ].copy()

    if frame.empty:
        fallback = pd.DataFrame(
            {
                "screen": "fallback_momentum_universe",
                "symbol": list(config.fallback_universe),
                "name": list(config.fallback_universe),
                "quote_type": "EQUITY",
                "exchange": "NMS",
                "price": pd.NA,
                "day_change_pct": pd.NA,
                "market_cap": pd.NA,
                "avg_volume_3m": pd.NA,
            }
        )
        reason = "fallback_momentum_universe"
        if failures:
            reason = f"fallback_momentum_universe ({'; '.join(f'{k}: {v}' for k, v in failures.items())})"
        return fallback, reason

    return frame, "yfinance_screeners"


def aggregate_candidates(candidate_rows: pd.DataFrame) -> pd.DataFrame:
    if candidate_rows.empty:
        return pd.DataFrame(
            columns=[
                "symbol",
                "name",
                "screen_hits",
                "screens",
                "screen_presence_score",
                "price",
                "day_change_pct",
                "market_cap",
                "avg_volume_3m",
            ]
        )

    grouped = candidate_rows.groupby("symbol", as_index=False).agg(
        name=("name", "first"),
        screen_hits=("screen", "count"),
        screens=("screen", lambda values: ", ".join(sorted(set(values)))),
        price=("price", "max"),
        day_change_pct=("day_change_pct", "max"),
        market_cap=("market_cap", "max"),
        avg_volume_3m=("avg_volume_3m", "max"),
    )
    max_hits = max(grouped["screen_hits"].max(), 1)
    grouped["screen_presence_score"] = grouped["screen_hits"] / max_hits
    return grouped.sort_values(["screen_hits", "market_cap"], ascending=[False, False]).reset_index(drop=True)


def download_adjusted_close(tickers: Iterable[str], period: str) -> pd.DataFrame:
    ticker_list = list(dict.fromkeys(tickers))
    if not ticker_list:
        raise ValueError("At least one ticker is required.")

    data = yf.download(ticker_list, period=period, interval="1d", auto_adjust=False, progress=False, threads=True)
    if data.empty:
        raise ValueError("No price data returned from Yahoo Finance.")

    if isinstance(data.columns, pd.MultiIndex):
        price_level = data.columns.get_level_values(0)
        target_col = "Adj Close" if "Adj Close" in price_level else "Close"
        prices = data[target_col].copy()
    else:
        target_col = "Adj Close" if "Adj Close" in data.columns else "Close"
        ticker = ticker_list[0]
        prices = data[[target_col]].copy()
        prices.columns = [ticker]

    if isinstance(prices, pd.Series):
        prices = prices.to_frame(name=ticker_list[0])

    return prices.dropna(axis=0, how="all").sort_index()


def download_benchmark_close(ticker: str, period: str) -> pd.Series:
    return download_adjusted_close([ticker], period=period).iloc[:, 0].dropna()

from __future__ import annotations
import sys from dataclasses import asdict from datetime import datetime, timezone from pathlib import Path
from .analytics import compute_security_metrics, correlation_matrix, portfolio_summary, rank_trending_stocks from .config import AnalysisConfig from .market_data import aggregate_candidates, download_adjusted_close, download_benchmark_close, fetch_screener_candidates from .reporting import ( build_data_quality_markdown, build_report_markdown, plot_correlation_heatmap, plot_normalized_prices, write_json, ) from .simulation import simulate_portfolio_paths, summarize_simulation
def ensure_directories(config: AnalysisConfig) -> None: config.data_dir.mkdir(parents=True, exist_ok=True) config.reports_dir.mkdir(parents=True, exist_ok=True) config.figures_dir.mkdir(parents=True, exist_ok=True)
def run_pipeline(config: AnalysisConfig | None = None) -> dict[str, Path]: resolved_config = config or AnalysisConfig() ensure_directories(resolved_config)
generated_at = datetime.now(timezone.utc) candidate_rows, selection_source = fetch_screener_candidates(resolved_config) candidate_universe = aggregate_candidates(candidate_rows) candidate_symbols = candidate_universe["symbol"].tolist()
if not candidate_symbols: raise ValueError("Candidate universe is empty after filtering.")
candidate_prices = download_adjusted_close(candidate_symbols, period=resolved_config.price_history_period) metrics = compute_security_metrics(candidate_universe, candidate_prices) top_selection = rank_trending_stocks(metrics, top_n=resolved_config.top_n)
top_symbols = top_selection["symbol"].tolist() top_prices = candidate_prices[top_symbols].dropna(how="any") benchmark = download_benchmark_close(resolved_config.benchmark_ticker, period=resolved_config.price_history_period) benchmark.name = resolved_config.benchmark_ticker
portfolio_table = portfolio_summary(top_prices, benchmark, risk_free_rate=resolved_config.risk_free_rate) correlation = correlation_matrix(top_prices) simulation_paths = simulate_portfolio_paths( top_prices, num_simulations=resolved_config.monte_carlo_simulations, num_trading_days=resolved_config.monte_carlo_days, random_seed=resolved_config.random_seed, ) simulation_summary = summarize_simulation(simulation_paths) data_as_of = str(top_prices.index.max().date())
normalized_plot = resolved_config.figures_dir / "top5_normalized_performance.png" correlation_plot = resolved_config.figures_dir / "top5_correlation_heatmap.png" plot_normalized_prices(top_prices, normalized_plot) plot_correlation_heatmap(correlation, correlation_plot)
top_selection_path = resolved_config.data_dir / "latest_top5_selection.csv" top_prices_path = resolved_config.data_dir / "latest_top5_prices.csv" portfolio_path = resolved_config.data_dir / "latest_portfolio_summary.csv" simulation_path = resolved_config.data_dir / "latest_monte_carlo_summary.csv" metadata_path = resolved_config.data_dir / "latest_run_metadata.json" report_path = resolved_config.reports_dir / "latest_top5_stock_report.md" dq_report_path = resolved_config.reports_dir / "data_quality_report.md"
top_selection.to_csv(top_selection_path, index=False) top_prices.to_csv(top_prices_path) portfolio_table.to_csv(portfolio_path, index=False) simulation_summary.rename("value").to_csv(simulation_path, header=True)
metadata = { "generated_at_utc": generated_at.isoformat(), "data_as_of": data_as_of, "selection_source": selection_source, "candidate_count": int(len(candidate_universe)), "selected_tickers": top_symbols, "config": {key: str(value) if isinstance(value, Path) else value for key, value in asdict(resolved_config).items()}, } write_json(metadata, metadata_path)
report_markdown = build_report_markdown( generated_at=generated_at, data_as_of=data_as_of, selection_source=selection_source, candidate_count=len(candidate_universe), top_selection=top_selection, portfolio_summary=portfolio_table, monte_carlo_summary=simulation_summary, figures={ "normalized_prices": str(normalized_plot.relative_to(resolved_config.project_root)), "correlation_heatmap": str(correlation_plot.relative_to(resolved_config.project_root)), }, ) report_path.write_text(report_markdown, encoding="utf-8")
dq_report = build_data_quality_markdown( generated_at=generated_at, candidate_count=len(candidate_universe), selected_count=len(top_symbols), price_rows=len(top_prices), missing_cells=int(top_prices.isna().sum().sum()), selection_source=selection_source, ) dq_report_path.write_text(dq_report, encoding="utf-8")
return { "top_selection": top_selection_path, "top_prices": top_prices_path, "portfolio_summary": portfolio_path, "monte_carlo_summary": simulation_path, "metadata": metadata_path, "report": report_path, "data_quality_report": dq_report_path, }
def main() -> None: outputs = run_pipeline() print("Invest-a-Bull pipeline completed successfully.") for label, path in outputs.items(): print(f"- {label}: {path}")
if __name__ == "__main__": if __package__ in {None, ""}: sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "src")) main()
